/**
 * The AI assistant's mark: its states, what each one MEANS, and the
 * motion tokens that make it feel like one thing moving rather than
 * several things animating.
 *
 * ## The mark
 *
 * Two opposing corner brackets closing in on a single solid dot.
 * Navy monoline strokes, one indigo dot in the centre. Generated by
 * the brand generator on 2026-10-22; the source SVGs live in
 * `public/brand/agent/`.
 *
 * The brackets are the "precisely here" of an editorial annotation;
 * the dot is the point of view. That gives the mark a natural motion
 * vocabulary: the brackets are the subject, the dot is the attention.
 *
 * ## Why the states exist
 *
 * An agent that is doing something should LOOK like it is doing
 * something. A static avatar next to a "Thinking…" line is the
 * opposite of premium, and it is also useless — the user cannot tell
 * "reading your resume" from "about to ask you a question" from
 * "couldn't apply the change".
 *
 * So the mark has seven states, and the chat UI drives them. Each one
 * is a real moment in the agent's work, not a decorative variant.
 */

/** The seven states the mark can be in. */
export type AgentMarkState =
  /** Nothing happening. Present, alive, quiet. */
  | 'idle'
  /** Reading the resume and the job description. */
  | 'reading'
  /** Found something worth telling the user about. Transient. */
  | 'verdict'
  /** Applying an edit to the document. */
  | 'working'
  /** The edit landed. */
  | 'applied'
  /** Needs a fact only the user has — asking, not telling. */
  | 'needs-you'
  /** Could not apply the change; stalled until the user answers. */
  | 'blocked';

export const AGENT_MARK_STATES: readonly AgentMarkState[] = [
  'idle',
  'reading',
  'verdict',
  'working',
  'applied',
  'needs-you',
  'blocked'
] as const;

export interface AgentMarkStateSpec {
  /** Short name for the UI. */
  readonly label: string;
  /** One line on what the state means. */
  readonly meaning: string;
  /** What causes the agent to enter this state. */
  readonly cause: string;
  /**
   * Whether the state is a MOMENT (it fires and then moves on) or a
   * MODE (it persists until something else happens). The chat UI
   * needs this: `verdict` should auto-return to `idle`, `working`
   * should not.
   */
  readonly transient: boolean;
}

export const AGENT_MARK_STATE_SPECS: Record<
  AgentMarkState,
  AgentMarkStateSpec
> = {
  idle: {
    label: 'Idle',
    meaning: 'Present, not working. The dot breathes so it never looks frozen.',
    cause: 'No task in flight.',
    transient: false
  },
  reading: {
    label: 'Reading',
    meaning: 'Looking through the document. The brackets scan apart and back.',
    cause: 'The agent is reading the resume or the job description.',
    transient: false
  },
  verdict: {
    label: 'Verdict',
    meaning: 'It found something. The brackets close in and the dot turns amber.',
    cause: 'A gap, a missing keyword, a line that is too long.',
    transient: true
  },
  working: {
    label: 'Working',
    meaning: 'Applying an edit. A radar ring pulses out from the dot.',
    cause: 'A tool call that changes the document.',
    transient: false
  },
  applied: {
    label: 'Applied',
    meaning: 'The change landed. The dot becomes a check.',
    cause: 'A tool call that succeeded.',
    transient: true
  },
  'needs-you': {
    label: 'Needs you',
    meaning: 'It is asking. The dot slides out to the bracket that marks the question.',
    cause: 'A required fact is missing — a date, a metric, which of two roles.',
    transient: false
  },
  blocked: {
    label: 'Blocked',
    meaning: 'Stalled. The brackets pull apart and the dot goes grey.',
    cause: 'A change could not be applied and the agent will not guess.',
    transient: false
  }
};

/**
 * Motion tokens.
 *
 * Two curves, used everywhere:
 *
 * - `easeOut` — a fast start and a long settle. Used for anything
 *   that ARRIVES: a state change, a pop, a check draw. This is what
 *   makes motion read as expensive rather than bouncy.
 * - `easeInOut` — symmetric. Used for anything that LOOPS, because a
 *   loop with an abrupt start and stop visibly ticks.
 *
 * The transition duration is deliberately long (420ms) for a mark
 * this small. A 24px glyph that moves has very little distance to
 * cover, and a fast transition reads as a glitch; a slow one reads as
 * deliberate.
 */
export const AGENT_MARK_MOTION = {
  /** Duration of a state-to-state transition. */
  transitionMs: 420,
  /** One-shot flourishes (the check draw, the verdict ping). */
  flourishMs: 560,
  /** The breathing pulse of the idle dot. */
  idlePulseMs: 4200,
  /** The reading scan. */
  scanMs: 2600,
  /** The working radar ring. */
  radarMs: 1700,
  easeOut: 'cubic-bezier(0.32, 0.72, 0, 1)',
  easeInOut: 'cubic-bezier(0.45, 0, 0.55, 1)'
} as const;

/**
 * The name the chat UI shows for the agent, and the name the agent
 * knows itself by.
 *
 * DECIDED: **Scout**. It goes ahead, checks the ground against the
 * job posting, and comes back with a report — which is exactly what
 * this agent does. It opens the conversation already informed, it
 * recommends rather than offers a menu, and it will not guess.
 *
 * This is the ONE place the name lives. The chat header, the
 * accessibility labels and the agent's own system prompt all read it
 * from here, so the product and the agent can never disagree about
 * who the agent is.
 *
 * (The shortlist was Scout / Wren / Gauge. Wren was the warmer
 * option; Gauge leaned on the measurement character. Scout won
 * because it describes the behaviour rather than the vibe, and the
 * behaviour is the thing worth branding.)
 */
export const AGENT_DISPLAY_NAME = 'Scout';

/* ------------------------------------------------------------------ */
/* Deriving the state from what the agent is actually doing            */
/* ------------------------------------------------------------------ */

/**
 * A persisted chat message, as far as the mark is concerned.
 *
 * Deliberately loose: the mark must work with a message row loaded
 * from the database as well as with one being streamed right now.
 */
export interface AgentMessageLike {
  role: 'user' | 'assistant';
  content: string;
  toolCalls?: unknown;
  toolResult?: unknown;
}

/** What the agent is doing right now. */
export interface AgentActivity {
  /** A reply is streaming. */
  isStreaming: boolean;
  /** A tool has been announced and its result has not arrived yet. */
  toolInFlight: boolean;
  /** The most recent assistant message, if the conversation has one. */
  lastAssistant?: AgentMessageLike | null;
}

/**
 * How long a MOMENT state holds before it settles back to idle.
 *
 * `applied` is short — the check draws in 560ms and then the mark
 * should not keep claiming something it already did. `blocked` and
 * `verdict` are longer because they carry information the user has to
 * read, and the mark is the only thing still on screen saying so.
 *
 * `needs-you` is deliberately NOT here: the agent is genuinely
 * waiting for an answer, and it stays in that state until the user
 * replies.
 */
export const AGENT_TRANSIENT_MS: Partial<Record<AgentMarkState, number>> = {
  applied: 1900,
  blocked: 2600,
  verdict: 3200
};

/** `true` when the state is a moment that settles on its own. */
export function isTransientAgentState(state: AgentMarkState): boolean {
  return AGENT_TRANSIENT_MS[state] !== undefined;
}

/**
 * The tool results on a message, normalised to `{ ok }`.
 *
 * Every tool in `lib/chat/tools/` returns `{ ok: true, result }` or
 * `{ ok: false, error }`, and the stream wraps that in
 * `{ id, result }`. So "did the tool succeed" is one field, and it is
 * the same field the "Changes applied" badge already reads.
 */
export function toolResultsOf(
  message: AgentMessageLike | null | undefined
): Array<{ ok: boolean }> {
  const raw = message?.toolResult;
  if (!Array.isArray(raw)) return [];
  return raw.map((entry) => {
    const inner = (entry as { result?: unknown } | null)?.result;
    const ok = (inner as { ok?: unknown } | null)?.ok;
    return { ok: ok === true };
  });
}

/**
 * The state the mark should show for a PERSISTED message.
 *
 * This is what the avatar next to a message in the transcript shows:
 * what happened in that turn. A turn that applied changes carries a
 * green check; a turn whose tool failed is grey; everything else is
 * the plain mark.
 */
export function agentStateForMessage(
  message: AgentMessageLike | null | undefined
): AgentMarkState {
  if (!message || message.role !== 'assistant') return 'idle';
  const results = toolResultsOf(message);
  if (results.length > 0) {
    return results.some((r) => r.ok) ? 'applied' : 'blocked';
  }
  // A tool call that was announced but never produced a result did
  // not land. That is a stall, not a neutral message.
  if (Array.isArray(message.toolCalls) && message.toolCalls.length > 0) {
    return 'blocked';
  }
  return 'idle';
}

/**
 * The LIVE state of the agent.
 *
 * The rules, in order:
 *
 * 1. A tool is running → `working`. The agent is measuring or
 *    editing, and that is the most important thing it could be doing.
 * 2. A reply is streaming → `reading`. It is composing.
 * 3. The last turn ended with a tool result → `applied` if any tool
 *    succeeded, `blocked` if none did.
 * 4. The last turn ended with a tool call but no result → `blocked`.
 * 5. The last turn ended with a question → `needs-you`. The agent is
 *    waiting on a fact only the user has. (A trailing question mark is
 *    a crude signal, but the agent's own voice spec says it asks for
 *    exactly ONE thing by name — "Your Dayforce role has no start
 *    date. What was it?" — so it is a reliable one in practice.)
 * 6. The last turn ended with a statement → `verdict`. The agent
 *    found something, or made a decision, and said so.
 * 7. Otherwise → `idle`.
 */
export function deriveAgentState(activity: AgentActivity): AgentMarkState {
  if (activity.toolInFlight) return 'working';
  if (activity.isStreaming) return 'reading';

  const last = activity.lastAssistant;
  if (!last) return 'idle';

  const results = toolResultsOf(last);
  if (results.length > 0) {
    return results.some((r) => r.ok) ? 'applied' : 'blocked';
  }
  if (Array.isArray(last.toolCalls) && last.toolCalls.length > 0) {
    return 'blocked';
  }

  const text = (last.content ?? '').trim();
  if (text.length === 0) return 'idle';
  return text.endsWith('?') ? 'needs-you' : 'verdict';
}

/**
 * A one-line description of what the agent is doing, for the chat
 * header. `null` means "nothing worth saying" — the header then shows
 * the resume name, as it always did.
 */
export function agentStateLabel(state: AgentMarkState): string | null {
  switch (state) {
    case 'reading':
      return 'Reading your resume';
    case 'working':
      return 'Working';
    case 'verdict':
      return 'Found something';
    case 'applied':
      return 'Change applied';
    case 'needs-you':
      return 'Waiting for you';
    case 'blocked':
      return 'Stopped — it needs your input';
    case 'idle':
    default:
      return null;
  }
}
